package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.TextView;import androidx.annotation.*;import androidx.fragment.app.Fragment;import com.google.android.material.button.MaterialButton;import java.util.*;
public class WeaknessCenterFragment extends Fragment{
 private WordRepository repo;private ProgressStore progress;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_weakness_center,c,false);repo=WordRepository.get(requireContext());progress=new ProgressStore(requireContext());List<Word> learned=new ArrayList<>();for(Word w:repo.all())if(progress.mastery(w.id)>0)learned.add(w);int[] weak=new int[4];for(Word w:learned)for(int d=0;d<4;d++)if(progress.dimensionLevel(w.id,d)<4)weak[d]++;int wrong=progress.wrongTotal(repo.all());int[] av=new int[4];for(int d=0;d<4;d++)av[d]=learned.isEmpty()?0:progress.dimensionAverage(learned,d);int priority=0;for(int d=1;d<4;d++)if(av[d]<av[priority])priority=d;String pname=dimName(priority);GrammarPoint gp=GrammarDiagnostics.recommended(progress);((TextView)v.findViewById(R.id.text_diag_overview)).setText("已接触 "+learned.size()+" / "+repo.size()+"词 · 最近7天正确率 "+progress.sevenDayAccuracy()+"% · 当前错词 "+wrong+"\n识义 "+av[0]+"% · 听力 "+av[1]+"% · 拼写 "+av[2]+"% · 口语 "+av[3]+"%");((TextView)v.findViewById(R.id.text_diag_priority)).setText(pname+"是当前最低项 · "+av[priority]+"%");((TextView)v.findViewById(R.id.text_diag_detail)).setText("建议先修复 "+pname+"弱项，再处理错词和语法。当前语法建议："+gp.title+"。系统会进一步区分你为什么错，而不是只记录“答错”。");((TextView)v.findViewById(R.id.text_diag_causes)).setText(causeSummary());MaterialButton bw=v.findViewById(R.id.button_diag_wrong),bm=v.findViewById(R.id.button_diag_meaning),bl=v.findViewById(R.id.button_diag_listening),bs=v.findViewById(R.id.button_diag_spelling),bp=v.findViewById(R.id.button_diag_speaking);bw.setText("❌ 错词本 · "+wrong+"词");bm.setText("识义弱项 · "+weak[0]+"词");bl.setText("听力弱项 · "+weak[1]+"词");bs.setText("拼写弱项 · "+weak[2]+"词");bp.setText("口语弱项 · "+weak[3]+"词");bw.setOnClickListener(x->((MainActivity)requireActivity()).openWrongWordRepair());bm.setOnClickListener(x->((MainActivity)requireActivity()).openPracticeMode("zh"));bl.setOnClickListener(x->((MainActivity)requireActivity()).openPracticeMode("listen"));bs.setOnClickListener(x->((MainActivity)requireActivity()).openPracticeMode("spell"));bp.setOnClickListener(x->((MainActivity)requireActivity()).openPracticeMode("speaking"));v.findViewById(R.id.button_diag_grammar).setOnClickListener(x->((MainActivity)requireActivity()).openGrammarDiagnosis());v.findViewById(R.id.button_diag_sentence_dictation).setOnClickListener(x->((MainActivity)requireActivity()).openSentenceDictation());List<Word> top=repo.wrongWords(progress);top.sort((a,b)->Integer.compare(progress.wrongCount(b.id),progress.wrongCount(a.id)));StringBuilder sb=new StringBuilder();for(int n=0;n<Math.min(8,top.size());n++){Word w=top.get(n);if(n>0)sb.append("\n");sb.append(n+1).append(". ").append(w.word).append(" · ").append(w.chinese).append(" · 错").append(progress.wrongCount(w.id)).append("次");}((TextView)v.findViewById(R.id.text_diag_top_wrong)).setText(sb.length()==0?"目前没有累计错词，继续保持。":sb.toString());return v;}
 private String causeSummary(){String[] k={ErrorCause.MEANING_CONFUSION,ErrorCause.LISTENING_CONFUSION,ErrorCause.SPELLING,ErrorCause.WORD_FORM,ErrorCause.ARTICLE_GENDER,ErrorCause.OMISSION,ErrorCause.WORD_ORDER,ErrorCause.PRONUNCIATION,ErrorCause.GRAMMAR,ErrorCause.RECALL};List<String> list=new ArrayList<>();for(String x:k){int n=progress.errorCauseCount(x);if(n>0)list.add(String.format(java.util.Locale.CHINA,"%04d|%s · %d次",9999-Math.min(9999,n),ErrorCause.label(x),n));}Collections.sort(list);StringBuilder sb=new StringBuilder();for(int i=0;i<Math.min(6,list.size());i++){if(i>0)sb.append("\n");sb.append("• ").append(list.get(i).substring(5));}if(sb.length()==0)return "还没有足够错误样本。继续做听力、拼写和句型练习后，这里会自动形成错误画像。";return "当前最常见："+ErrorCause.label(progress.topErrorCause())+"\n"+sb;}
 private String dimName(int d){switch(d){case ProgressStore.DIM_LISTENING:return "听力";case ProgressStore.DIM_SPELLING:return "拼写";case ProgressStore.DIM_SPEAKING:return "口语";default:return "识义";}}
}
